insert into public.admin_tasks (code, task_no, is_done, category, task, assigned_to, due_text, due_date, status, done_on, attachments, updated_at) values
  ('109', 109, false, 'IT', '**One-click onboarding: Accept → everything.** On Accept → Enroll: parent portal login created (wire the `create-parent` Edge Function to the Admissions page; temp password + must-change flag; welcome e-mail through Brevo), class-update form roster refreshed on a timer, attendance sheet row added by the attendance Apps Script, and a **Print welcome package** button on the Student Profile (welcome letter, portal login letter, grade supply list, orientation pack) replacing the scratchpad generator. Dev first; President deploys the Edge Function and pastes the two Apps Scripts', 'Claude builds → Muneeb (President) deploys', '2026-10-21', '2026-10-21', 'Not started', null, '[]'::jsonb, now()),
  ('112', 112, false, 'IT', '**One-click Suspend / Withdraw / Reinstate a student (requested by the President 2026-10-09).** Student Profile button opens a dialog: type (**Suspended** = may return, **Withdrawn** = left), effective date, reason, close fee plan (default on), suspend the parent login if no other active child (default on). One RPC does it all in one transaction: archive, enrollment status (`suspended` added to the check) + exit date + reason, fee plan closed, parent `suspended`, audit log. **Reinstate** reverses it. Attendance sheet rows and the class-update roster follow automatically through the hourly roster sync built in #109 (adds active students, removes suspended/withdrawn). Replaces the manual SQL in #104. Dev first; President runs the SQL in prod', 'Claude builds → Muneeb (President) runs prod SQL', '2026-10-23', '2026-10-23', 'Not started', null, '[]'::jsonb, now()),
  ('116', 116, false, 'IT', '**UTC date in Accept → Enroll (UTC audit item 1, 2026-10-09).** `accept_applicant` uses `current_date` (UTC) for enrollment date, admission date, the "Created by Accept → Enroll on" note and the fee plan''s start month, so a student accepted after ~5 PM Pacific gets tomorrow''s date (and on the last evening of a month the fee plan would start next month). Fix: use `(now() at time zone ''America/Los_Angeles'')::date` in the function (new phase SQL, dev → prod). Also correct student 10018''s admission/enrollment date to 2026-10-07 (accepted that evening) once confirmed by the President', 'Claude builds → Muneeb (President) runs SQL', '2026-10-23', '2026-10-23', 'Not started', null, '[]'::jsonb, now()),
  ('117', 117, false, 'IT', '**UTC date on website applications (UTC audit item 2).** `applicants.application_date` defaults to `current_date` (UTC) and the website admission form does not send a date, so an evening application shows "Applied" the next day. Fix: column default `(now() at time zone ''America/Los_Angeles'')::date` (same phase SQL as the Accept → Enroll fix)', 'Claude builds → Muneeb (President) runs SQL', '2026-10-23', '2026-10-23', 'Not started', null, '[]'::jsonb, now()),
  ('120', 120, false, 'IT', '**Fee-reminder "once a month" check compares months in UTC (UTC audit item 5, low risk).** `run_daily_notifications` checks `date_trunc(''month'', x.created_at) = date_trunc(''month'', now())` in UTC. Harmless while the job runs at ~9:30 AM Pacific; would misfire only if the schedule moved to the evening. Fix when next touching that function: compare in America/Los_Angeles', 'Claude', '2026-12-31', '2026-12-31', 'Not started', null, '[]'::jsonb, now()),
  ('121', 121, false, 'IT', '**Website countdown / school-year progress use the visitor''s clock (UTC audit item 6, cosmetic).** `js/main.js` builds `new Date(''2026-08-26T09:00:00'')` in the visitor''s own time zone, so out-of-state visitors see it a few hours off. Fix: pin the times to Pacific (`-07:00`/`-08:00` offsets). Dev → prod', 'Claude', '2026-12-31', '2026-12-31', 'Not started', null, '[]'::jsonb, now()),
  ('111', 111, false, 'Students & Families', '**Finish onboarding new KG student 10018 (started 2026-10-08).** Done: portal record, parents + emergency contact, parent login, welcome package PDFs, class-update roster (grade-based, nothing to add); Red Comet enrolment + Choice Transfer submitted 10-14 (confirmation filed); birth certificate + immunization printout filed; **attendance confirmed syncing (present 10-12, late 10-13)**. Remaining: (1) print and hand over the package; (2) ~~10-08 backfill~~ not needed (President 2026-10-14); (3) ~~refreshRoster~~ run by the President 2026-10-14 — she is in the Qur''an form dropdown; (4) Kent SD Choice Transfer **approval** e-mail → file it; (5) WA **CIS form** completed from the registry printout and signed; (6) parent completes the **media consent** and **allergy/medical** portal forms (emergency contact already on file); (7) add her to the Red Comet weekly check-in list (#84) when her Buzz login arrives.', 'Muneeb (Principal)', '2026-10-16', '2026-10-16', 'In progress', null, '[]'::jsonb, now()),
  ('125', 125, false, 'Finance', '**October 2026 tuition into QuickBooks as it arrives** (so receipts like #123 are backed by QBO straight away, not only at the November close): record each October Zelle/cash tuition receipt on the date received — starting with the 10-01 $300 from #123; **when the President''s $1,260 Zelle of 10-10 (conf. p1zthyd6m) appears in the …8048 feed, MATCH it to the existing Bank Deposit of 10-10 — do not add it again (#126)** — and match it to the portal''s Admin → Fees row. Wrap up in the October close (due 2026-11-10) **Progress 2026-10-10:** …8048 feed (through 10-06) cleared — nine October tuition Zelles posted to Tuition Income / Tuition Program on the date received: 10-01, 10-02 (the #123 family), five on 10-05 and 10-06, total **$2,850** (eight × $300 + one $450 = KG Sept $150 reduced + Oct $300, posted to a **new QBO customer for student 10018''s family** created today; one row had been auto-matched to the wrong family and one had no customer — both corrected). QBO posted $8,660.77 vs bank $7,400.77: the $1,260 gap is the President''s 10-10 Zelle already recorded as a deposit — **match it when it appears**. Still to do: later October arrivals; check the portal Admin → Fees shows the same nine payments', 'Claude (with Muneeb (accountant) signed in)', '2026-10-24', '2026-10-24', 'In progress', null, '[]'::jsonb, now()),
  ('127', 127, false, 'IT', '**Rich link-preview card for falahacademywa.org (requested by the President 2026-10-10).** When the site link is pasted in Gmail, WhatsApp, LinkedIn or Facebook it should show a large card like the one on the President''s personal portfolio (reference screenshot: name, one-line tagline, small topic chips, site address on a clean 1200×630 image). Today the site already has Open Graph tags on every page, but `og:image` is the square `images/logo.jpg` and `twitter:card` is `summary`, so previews come out small. Do: design `images/og-card.png` (1200×630: logo, "Falah Academy", "Kent''s First Full-Time Islamic School", chips Pre-K · KG · Grade 1 · Qur''an · Islamic Studies · Accredited academics, falahacademywa.org; site colours), set `og:image` + `og:image:width/height/alt` and `twitter:card = summary_large_image` on all pages (page-specific titles/descriptions where useful), dev → prod, then check with the Facebook Sharing Debugger / LinkedIn Post Inspector and a test e-mail. Optionally add the site link to the school e-mail signature', 'Claude', '2026-11-30', '2026-11-30', 'Not started', null, '[]'::jsonb, now()),
  ('128', 128, false, 'Marketing', '**First monthly search check** (new recurring line in DEADLINES, with the monthly close): Google Search Console + Bing Webmaster Tools — clicks and top search terms, pages "not indexed" (Google showed 6 on 2026-10-10) and why, sitemap status, Bing''s first performance data. One-paragraph note into TASKS; fixes become their own rows', 'Claude (with the President signed in)', '2026-11-10', '2026-11-10', 'Not started', null, '[]'::jsonb, now()),
  ('129', 129, false, 'IT', '**Bing Site Scan of falahacademywa.org, once** (Bing Webmaster Tools → Site Scan, free): crawl the site for broken links, missing titles/descriptions, oversized pages, etc.; fix what it finds dev → prod. Optional add-on: IndexNow key file so Bing hears about page changes immediately', 'Claude', '2026-12-15', '2026-12-15', 'Not started', null, '[]'::jsonb, now()),
  ('130', 130, false, 'IT', '**Dev portal password-reset link returns to the prod path.** `platform-src/src/pages/Login.tsx` line 31 sets `redirectTo: window.location.origin + "/platform/#/change-password"`; on dev (`/falahacademywa-dev/platform/`) that is prod''s path, not in dev''s allow-list, so Supabase falls back to the dev home page and the tester lands on login instead of Change password. Fix: `window.location.origin + window.location.pathname + "#/change-password"` (same result on prod). Dev → prod, rebuild bundles, re-test with the dev test login', 'Claude', '2026-12-15', '2026-12-15', 'Not started', null, '[]'::jsonb, now()),
  ('4', 4, false, 'Executive Office', '**2027 budget + payroll compensation approval by the board (written consent, no meeting needed).** Deferred 2026-09-30 by the President: each teacher''s monthly pay is under the bylaws'' $5,000 board threshold, so monthly payroll runs on the President''s written approval of the pay list (bylaws: over $2,000 = President''s written approval). The bylaws still require a budget adopted before each fiscal year (calendar year), and board-set compensation is what the 990 asks about, so the five roles and rates go into the 2027 budget vote: $12,000/month gross at target rates (Grade 1 $3,000, KG $2,500, Pre-K teacher $2,500, Pre-K assistant $1,000, Qur''an $3,000), about $13,380/month all-in, $133,800 over 10 school months; floor scenario $9,500 gross. Claude drafts the one-page consent in late November from the workbook; the four directors sign by e-mail; replies filed as the minute in `records/10_Policies & Governance`', 'Muneeb (President); Claude drafts', '2026-12-15', '2026-12-15', 'Not started', null, '[{"name": "2026-27 Teacher Payroll Budget (W-2 from 2026-10-01).xlsx", "path": "4/2026-27-Teacher-Payroll-Budget-W-2-from-2026-10-01-.xlsx", "size": 7798}]'::jsonb, now()),
  ('8', 8, false, 'Legal & Compliance', '**City of Kent business license** applied via FileLocal 2026-09-24 (nonprofit fee exemption requested in the notes; 501(c)(3) letter to be provided if Kent asks). Waiting for Kent to issue the license / City Account Number. Then: save the license PDF to `records/01_Corporate & Legal/03. Registrations & Certificates`, record the FileLocal login in `docs/accounts.md`. State license needs nothing (UI, L&I, tax registration all Active) **Headcount:** application said 4 employees, actual is 5 (all five move to W-2 on 10-01); no fee effect (nonprofit exempt) — give the city 5 if they call, and restate at the Dec 31 renewal', 'Muneeb (President)', '2026-10-15', '2026-10-15', 'Waiting', null, '[]'::jsonb, now()),
  ('11', 11, false, 'Finance', 'Optional: one paid CPA/payroll hour for sign-off; evaluate IRS VCSP (Form 8952) for the 2025 contractor period', 'Muneeb (President)', '2026-10-31', '2026-10-31', 'Not started', null, '[]'::jsonb, now()),
  ('12', 12, false, 'HR', '**Staff payroll onboarding (five W-2 staff) — checked in QBO Payroll 2026-10-10.** ✅ Pre-K, Qur''an and KG teachers complete (direct deposit, W-4, salary, workers'' comp 6103-01; the Qur''an teacher''s Job & pay / workers'' comp cards now filled). 🔵 **Grade 1 teacher:** has not finished the Workforce self-onboarding (no bank details → paper check only) — she is out of the country; send the QBO reminder when she is back. 🔵 **Pre-K assistant:** finished her part (bank, W-4) but the school side is empty — job title, hourly pay ≥ $17.13, weekly hours, workers'' comp 6104-01, SOC 25-9045 — President confirms rate and hours in about a week (#99). ❌ **Form I-9 for all five** — **2026-10-10:** none on file yet (only one List B photo); current blank I-9 (edition 01/20/25, expires 2027-05-31) filed in `16_Employees/01. Employee Details/`, the 2019 copy marked SUPERSEDED; I-9 e-mail with the form **sent 2026-10-10** to the four staff here (BCC); separate draft for the Grade 1 teacher (Section 1 now, documents on her return, plus finish the QBO Workforce invite) prepared for the President to attach and send; **in-person document check Thursday 2026-10-15**; (Section 2 in person, original documents, keep on file; was due within 3 business days of 10-01 — complete now, date it the day it is done; Grade 1 teacher on return) . ❓ President to decide: (a) work location in QBO shows a home address for all four teachers → change to the school, 25650 101st Ave SE; (b) Qur''an teacher''s hire date 08/31 vs W-2 start 10/01. Copies of W-4/I-9 → each person''s `16_Employees/<person>/02. Tax Forms`', 'Muneeb (Principal)', '2026-10-29', '2026-10-29', 'Waiting', null, '[{"name": "Form I-9 blank (edition 01-20-25, expires 2027-05-31).pdf", "path": "12/Form-I-9-blank-edition-01-20-25-expires-2027-05-31-.pdf", "size": 524095}]'::jsonb, now()),
  ('13', 13, false, 'HR', 'DSHS new-hire reports within 20 days of Oct 1 for all five (QuickBooks can send them). Note: the Qur''an teacher''s QBO hire date is 08/31/2026, so his shows as due 09-20 — file it with the others; no first-offence penalty', 'Muneeb (accountant)', '2026-10-21', '2026-10-21', 'Not started', null, '[]'::jsonb, now()),
  ('14', 14, false, 'Operations', '**Posters up at school** — checklist prepared 2026-10-10: `records/07_HR & Policies/06. Workplace Posters/Workplace Posters Checklist 2026.md`. **8 free posters**: L&I Your Rights as a Worker (F700-074-000), Job Safety and Health Law (F416-081-909), If a Job Injury Occurs — State Fund (F242-191-909); ESD Unemployment Benefits (EMS 9874), Paid Family & Medical Leave, Domestic Violence Resources (EMS 10427); federal FLSA (WHD 1088) and EPPA; plus the USERRA notice and the original L&I Certificate of Workers'' Comp Coverage (RCW 51.04.120; it lists the home address — consider asking L&I 360-902-4817 to add the school). EEO and FMLA not required at our size. **Links (verified 2026-10-10):** (1) L&I Your Rights as a Worker https://lni.wa.gov/forms-publications/F700-074-000.pdf · (2) L&I Job Safety and Health Law https://lni.wa.gov/forms-publications/F416-081-909.pdf · (3) L&I If a Job Injury Occurs (State Fund) https://lni.wa.gov/forms-publications/F242-191-909.pdf — to **order the three L&I posters free by mail**: https://lni.wa.gov/forms-publications/required-workplace-posters · (4) ESD Unemployment Benefits https://esd.wa.gov/media/pdf/315/esd-unemployment-benefits-posterpdf · (5) Paid Family & Medical Leave 2026 https://paidleave.wa.gov/app/uploads/2025/12/Mandatory-poster-2026.pdf · (6) ESD Domestic Violence Resources https://esd.wa.gov/media/pdf/313/domesticviolence-poster190812pdf (write a local DV program in the blank space) · (7) US DOL FLSA minimum wage https://www.dol.gov/agencies/whd/posters/flsa · (8) US DOL Employee Polygraph Protection https://www.dol.gov/agencies/whd/posters/employee-polygraph-protection-act · plus USERRA https://www.dol.gov/agencies/vets/programs/userra/poster. ESD, Paid Leave and DOL posters are download-and-print (free). **Placement agreed 2026-10-10:** inside the classroom cabinet door (unlocked, used daily by the teachers) + a WhatsApp note to staff saying where they are. **Left (President):** print or order free, post in the staff area at Al Huda, photo into that folder', 'Muneeb (Principal)', '2026-10-15', '2026-10-15', 'Not started', null, '[]'::jsonb, now()),
  ('15', 15, false, 'HR', '**New-hire notice packet to each teacher** — **drafted 2026-10-10** by Claude (`scripts/make-newhire-packet.py`): `records/07_HR & Policies/05. New-Hire Notices/Falah Academy - New-Hire Notice Packet 2026 (Paid Sick Leave + State Programs).pdf`. Page 1 = the **Paid Sick Leave Benefits Notification** (the one individual notice WA requires by the first day; wording follows L&I form F700-191-000 rev. 02-2026) with an acknowledgment block; page 2 = pay and state programs (deductions, Paid Leave, WA Cares, unemployment, workers'' comp). Paid Leave and ESD require **posters**, not individual notices at hire (→ #14). **On hold 2026-10-10 — the President is thinking it through.** Note: only page 1 (sick-leave notice) is legally required, by the employee''s first day (W-2 started 2026-10-01); electronic delivery (email/WhatsApp PDF) is enough, no signature needed. **Left:** President confirms two policy points — start date = W-2 start **2026-10-01**, and hours above 40 at year end **do not carry over** — then prints five copies, each teacher signs page 1, signed copies scanned into each person''s file in `16_Employees`', 'Muneeb (Principal)', '2026-10-15', '2026-10-15', 'On hold', null, '[]'::jsonb, now()),
